<div class="mx-auto flex h-14 w-full max-w-[340px] items-center justify-center">
    <a class="group inline-flex h-11 w-full items-center justify-center gap-3 rounded-full border border-slate-500 bg-white px-4 text-sm font-medium tracking-[.01em] text-slate-900 shadow-sm transition hover:-translate-y-0.5 hover:shadow-lg hover:shadow-slate-900/10 focus-visible:outline-none focus-visible:ring-4 focus-visible:ring-blue-100 active:translate-y-0 active:scale-[.98]" href="/auth/google" aria-label="Tiếp tục với Google" data-google-sign-in>
        <span class="relative grid size-5 shrink-0 place-items-center" aria-hidden="true"><svg class="size-5 transition duration-300" viewBox="0 0 18 18" focusable="false" data-google-icon><path fill="#4285F4" d="M17.64 9.2c0-.64-.06-1.25-.16-1.84H9v3.48h4.84a4.14 4.14 0 0 1-1.8 2.72v2.26h2.91c1.7-1.56 2.69-3.86 2.69-6.62z"/><path fill="#34A853" d="M9 18c2.43 0 4.47-.8 5.96-2.16l-2.91-2.26c-.8.54-1.82.86-3.05.86-2.35 0-4.35-1.59-5.06-3.73H.93v2.33A9 9 0 0 0 9 18z"/><path fill="#FBBC05" d="M3.94 10.71a5.41 5.41 0 0 1 0-3.42V4.96H.93a9 9 0 0 0 0 8.08l3.01-2.33z"/><path fill="#EA4335" d="M9 3.58c1.32 0 2.5.45 3.44 1.35l2.58-2.58C13.46.89 11.43 0 9 0A9 9 0 0 0 .93 4.96l3.01 2.33C4.65 5.17 6.65 3.58 9 3.58z"/></svg><span class="material-symbols-outlined absolute animate-spin text-[20px] text-blue-700" aria-hidden="true" data-google-spinner hidden>progress_activity</span><span class="material-symbols-outlined absolute text-[20px] text-green-600" aria-hidden="true" data-google-check hidden>check_circle</span></span>
        <span data-google-label>Tiếp tục với Google</span>
    </a>
    <p class="sr-only" role="status" aria-live="polite" data-google-live></p>
</div>
<script>
(function(){const root=document.currentScript.previousElementSibling,button=root.querySelector('[data-google-sign-in]'),label=root.querySelector('[data-google-label]'),live=root.querySelector('[data-google-live]'),googleIcon=root.querySelector('[data-google-icon]'),spinner=root.querySelector('[data-google-spinner]'),check=root.querySelector('[data-google-check]');let timer=0;const show=function(element){if(element){element.hidden=false;element.classList.remove('hidden')}};const hide=function(element){if(element){element.hidden=true;element.classList.add('hidden')}};hide(spinner);hide(check);button.addEventListener('click',function(event){if(button.classList.contains('is-busy')||button.classList.contains('is-ok')){event.preventDefault();return}event.preventDefault();button.classList.add('is-busy');button.setAttribute('aria-busy','true');hide(googleIcon);show(spinner);hide(check);label.textContent='Đang kết nối…';live.textContent='Đang kết nối với Google';timer=window.setTimeout(function(){button.classList.remove('is-busy');button.classList.add('is-ok');button.removeAttribute('aria-busy');hide(googleIcon);hide(spinner);show(check);label.textContent='Đã kết nối';live.textContent='Đã kết nối với Google';window.setTimeout(function(){window.location.assign(button.href)},350)},1100)});window.addEventListener('pagehide',function(){window.clearTimeout(timer)},{once:true})}());
</script>


